const req = $('Set - Extract Request Data1').first().json;

if (!items.length) {
  throw new Error('Application not found: ' + req.application_id);
}

const app = items[0].json;

// Inject refinement_prompt into matching screening question
if (
  req.question_id &&
  req.refinement_prompt &&
  Array.isArray(app.screening_questions)
) {
  app.screening_questions = app.screening_questions.map(q => {
    if (q.id === req.question_id) {
      return {
        ...q,
        refinement_prompt: req.refinement_prompt
      };
    }
    return q;
  });
}

return [{
  json: {
    request_id: req.request_id,
    mode: req.mode,
    callback_url: req.callback_url,
    recruiter_instruction: req.recruiter_instruction || '',
    force_regenerate: req.force_regenerate || false,
    provided_existing_questions: req.existing_questions || [],
    application: app,
    application_id: app.id || req.application_id,
    candidate_id: app.candidate_id,
    job_opening_id: app.job_opening_id
  }
}];

const x = $json;

const questions = x.application?.screening_questions || [];

const targetQuestion = questions.find(
  q => q.refining === true && q.refinement_prompt
);

if (!targetQuestion) {
  throw new Error(
    "No question marked for refinement was found."
  );
}

const prompt = `You are helping a recruiter refine a screening question.

Your task is to improve ONLY the provided question based on the refinement request.

Rules:
- Modify only this single question.
- Keep the same order.
- Keep the same difficulty unless the refinement explicitly requires otherwise.
- Keep the question relevant to the candidate and the role.
- Generate exactly ONE replacement question.
- Return only valid JSON.
- No markdown.
- No explanation.

Refinement request:
${targetQuestion.refinement_prompt}

Question to refine:
${JSON.stringify(targetQuestion, null, 2)}

Application context:
${JSON.stringify({
  fuzzy_score: x.application.fuzzy_score,
  match_reason: x.application.match_reason,
  strengths: x.application.strengths,
  skill_gaps: x.application.skill_gaps
}, null, 2)}

Return exactly:

{
  "question": {
    "id": "${targetQuestion.id}",
    "order": ${targetQuestion.order},
    "difficulty": "${targetQuestion.difficulty}",
    "question": "updated question text",
    "reason": "why this updated question is relevant"
  }
}`;

return [{
  json: {
    ...x,
    target_question_id: targetQuestion.id,
    target_question: targetQuestion,
    prompt
  }
}];

const mode=$json.mode||'generate';
const candidate=$json.candidate||{};
const app=$json.application||{};
const job=$json.job_opening||{};
const skills=$json.approved_skills||[];
const resumeText=(candidate.resume_text||'').slice(0,8000);
const provided=$json.provided_existing_questions||[];
const existing=provided.length?provided:(app.screening_questions||[]);
const instruction=$json.recruiter_instruction||'';
let prompt;
if(mode==='regenerate'){
prompt=`You are helping a recruiter refine screening questions.

Regenerate the screening questions using the recruiter instruction.

Rules:
- Preserve candidate-specific relevance.
- Keep questions tied to the resume and job opening.
- Improve or replace the previous questions based on the instruction.
- Return exactly 10 questions.
- Use difficulty distribution: 3 easy, 4 medium, 3 hard.
- Return only valid JSON. No markdown. No explanation.

Recruiter instruction:
${instruction}

Existing questions:
${JSON.stringify(existing,null,2)}

Job opening:
${JSON.stringify(job,null,2)}

Approved weighted skills:
${JSON.stringify(skills,null,2)}

Candidate:
${JSON.stringify(candidate,null,2)}

Application match context:
${JSON.stringify({fuzzy_score:app.fuzzy_score,match_reason:app.match_reason,strengths:app.strengths,skill_gaps:app.skill_gaps},null,2)}

Candidate resume:
${resumeText}

Return this exact JSON:
{"questions":[{"order":1,"difficulty":"easy","question":"string","reason":"why this question is relevant to this candidate"}]}`;
}else{
prompt=`You are a technical interviewer generating personalised screening questions.

Generate screening questions for this specific candidate and this specific job.

Rules:
- Questions must be based on the candidate resume, matched skills, skill gaps, and job opening.
- Do not generate generic questions only.
- Include questions that verify claimed experience.
- Include questions that test gaps or weaker areas.
- Generate exactly 10 questions: 3 easy, 4 medium, 3 hard.
- Keep questions clear and practical.
- Return only valid JSON. No markdown. No explanation.

Job opening:
${JSON.stringify(job,null,2)}

Approved weighted skills:
${JSON.stringify(skills,null,2)}

Candidate:
${JSON.stringify(candidate,null,2)}

Application match context:
${JSON.stringify({fuzzy_score:app.fuzzy_score,match_reason:app.match_reason,strengths:app.strengths,skill_gaps:app.skill_gaps},null,2)}

Candidate resume:
${resumeText}

Return this exact JSON:
{"questions":[{"order":1,"difficulty":"easy","question":"string","reason":"why this question is relevant to this candidate"}]}`;
}
return {json:{...$json,prompt}};

function parseJSON(value){if(typeof value==='object'&&value!==null)return value;let text=String(value||'').trim();text=text.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```$/i,'').trim();const first=text.indexOf('{');const last=text.lastIndexOf('}');if(first>=0&&last>first)text=text.slice(first,last+1);return JSON.parse(text);}
const raw=$json.output||$json.text||$json.response||$json.message;const parsed=parseJSON(raw);let questions=Array.isArray(parsed.questions)?parsed.questions:[];
questions=questions.slice(0,10).map((q,index)=>({order:Number(q.order||index+1),difficulty:['easy','medium','hard'].includes(String(q.difficulty||'').toLowerCase())?String(q.difficulty).toLowerCase():(index<3?'easy':index<7?'medium':'hard'),question:String(q.question||'').trim(),reason:String(q.reason||'').trim()})).filter(q=>q.question);
if(!questions.length)throw new Error('AI returned no valid questions');
return {json:{...$json,questions,question_count:questions.length}};

let x;

try {
  x = $('Code - Parse and Validate Questions1').first().json;
} catch (e) {
  x = $('Code - Parse and Apply Refined Question').first().json;
}

const questions =
  x.questions ||
  x.screening_questions ||
  [];

return [{
  json: {
    request_id: x.request_id,
    mode: x.mode,

    status: "ready",
    processing_status: "ready",

    message:
      x.refined_question
        ? "Question refined successfully."
        : x.mode === "regenerate"
          ? "Screening questions regenerated successfully."
          : "Screening questions generated successfully.",

    application_id: $('Webhook - ATS Questions').first().json.body.application_id,
    candidate_id: x.candidate_id,
    job_opening_id: x.job_opening_id,

    // <-- This is what the callback expects
    questions,

    completed_at: new Date().toISOString()
  }
}];

function parseJSON(value) {
  if (typeof value === 'object' && value !== null) return value;

  let text = String(value || '').trim();
  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  return JSON.parse(text);
}

const parsed = parseJSON($json.output);

if (!parsed.question) {
  throw new Error('AI did not return a refined question');
}

const refinedQuestion = parsed.question;

// Get original payload
const source = $('Code - Build Already Ready Response1').first().json;

const screeningQuestions =
  source.application.screening_questions || [];

const updatedQuestions = screeningQuestions.map(q => {
  if (q.id === refinedQuestion.id) {
    return {
      ...q,
      question: refinedQuestion.question,
      reason: refinedQuestion.reason,
      difficulty: refinedQuestion.difficulty,
      refining: false,
      refinement_prompt: null
    };
  }

  return {
    ...q,
    refining: false
  };
});

return {
  json: {
    ...source,
    refined_question: refinedQuestion,
    questions: updatedQuestions,
    question_count: updatedQuestions.length
  }
};
